#include <bits/stdc++.h>
using namespace std;
int main(){
    int n, B;
    cin >> n >> B;
    vector<int> a(n);
    for (auto &x : a) cin >> x;
    int SZ = 1 << B, FULL = SZ - 1;
    vector<int> rep(SZ, -1);
    for (int i = 0; i < n; i++) rep[a[i]] = a[i];
    for (int b = 0; b < B; b++) {
        for (int mask = 0; mask < SZ; mask++) {
            if (mask & (1 << b)) {
                if (rep[mask] == -1 && rep[mask ^ (1 << b)] != -1)
                    rep[mask] = rep[mask ^ (1 << b)];
            }
        }
    }
    for (int i = 0; i < n; i++) {
        int comp = FULL ^ a[i];
        cout << rep[comp] << (i + 1 < n ? ' ' : '\n');
    }
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    int n; cin >> n;
    vector<vector<long long>> cost(n, vector<long long>(n));
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            cin >> cost[i][j];
    int FULL = 1 << n;
    const long long INF = LLONG_MAX / 2;
    vector<vector<long long>> dp(FULL, vector<long long>(n, INF));
    dp[1][0] = 0;
    for (int mask = 1; mask < FULL; mask++) {
        if (!(mask & 1)) continue; // city 0 always visited first
        for (int i = 0; i < n; i++) {
            if (!(mask & (1 << i))) continue;
            if (dp[mask][i] == INF) continue;
            for (int j = 0; j < n; j++) {
                if (mask & (1 << j)) continue;
                long long nc = dp[mask][i] + cost[i][j];
                int nmask = mask | (1 << j);
                if (nc < dp[nmask][j]) dp[nmask][j] = nc;
            }
        }
    }
    long long best = INF;
    for (int i = 1; i < n; i++)
        best = min(best, dp[FULL - 1][i] + cost[i][0]);
    if (n == 1) best = 0;
    cout << best << "\n";
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    int n; cin >> n;
    vector<long long> a(n);
    for (auto &x : a) cin >> x;
    const int BITS = 60;
    vector<long long> basis(BITS, 0);
    for (long long x : a) {
        for (int b = BITS - 1; b >= 0; b--) {
            if (!((x >> b) & 1)) continue;
            if (!basis[b]) { basis[b] = x; break; }
            x ^= basis[b];
        }
    }
    long long res = 0;
    for (int b = BITS - 1; b >= 0; b--) {
        if ((res ^ basis[b]) > res) res ^= basis[b];
    }
    cout << res << "\n";
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    int n; cin >> n;
    vector<long long> a(n);
    for (auto &x : a) cin >> x;
    const int BITS = 60;
    vector<long long> basis(BITS, 0);
    int rnk = 0;
    for (long long x : a) {
        for (int b = BITS - 1; b >= 0; b--) {
            if (!((x >> b) & 1)) continue;
            if (!basis[b]) { basis[b] = x; rnk++; break; }
            x ^= basis[b];
        }
    }
    long long ans = 1LL << rnk;
    cout << ans << "\n";
}

#include <bits/stdc++.h>
using namespace std;
const int BITS = 20;
struct Node { int ch[2] = {-1, -1}; };
vector<Node> trie;
int newNode() { trie.push_back(Node()); return (int)trie.size() - 1; }
void insertNum(int x) {
    int cur = 0;
    for (int b = BITS - 1; b >= 0; b--) {
        int bit = (x >> b) & 1;
        if (trie[cur].ch[bit] == -1) trie[cur].ch[bit] = newNode();
        cur = trie[cur].ch[bit];
    }
}
int queryMax(int x) {
    int cur = 0, res = 0;
    for (int b = BITS - 1; b >= 0; b--) {
        int bit = (x >> b) & 1;
        int want = bit ^ 1;
        if (trie[cur].ch[want] != -1) { res |= (1 << b); cur = trie[cur].ch[want]; }
        else cur = trie[cur].ch[bit];
    }
    return res;
}
int main(){
    int n; cin >> n;
    vector<int> a(n);
    for (auto &x : a) cin >> x;
    trie.clear();
    newNode(); // root = index 0
    insertNum(a[0]);
    int best = 0;
    for (int i = 1; i < n; i++) {
        best = max(best, queryMax(a[i]));
        insertNum(a[i]);
    }
    cout << best << "\n";
}
